public static void main(String[] args) throws IOException {
    int[] crons = new int[6];
    int[] cronss = new int[]{1, 5, 10, 50, 100, 500};
    for (int i = 0; i < 6; i++) {
        crons[i] = nextInt();
    }
    int N = nextInt();
    int[] Xs = new int[N];
    for (int i = 0; i < N; i++) {
        Xs[i] = nextInt();
    }
    for (int X : Xs) {
        int[] tempCrons = crons.clone(); // Create a copy of the original coin counts
        int cron = 0;
        for (int i = 5; i >= 0 && X > 0; i--) {
            cron = X / cronss[i];
            int coinsUsed = Math.min(cron, tempCrons[i]);
            X -= coinsUsed * cronss[i];
            tempCrons[i] -= coinsUsed; // Correctly update the number of coins remaining in the temporary array
        }
        if (X > 0) {
            System.out.println("No");
            return;
        }
        crons = tempCrons; // Update the original coin counts only if the current amount can be paid
    }
    System.out.println("Yes");

    out.flush();
}

